/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
uris=[]
for p in r.pages:
    for a in p.get('/Annots',[]):
        o=a.get_object()
        action=o.get('/A')
        if action and action.get('/URI'):
            u=str(action['/URI'])
            if u not in uris: uris.append(u)
print('\\n'.join(uris))
PY"
